#include "tigersheets/session.hpp"
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
Json source(){Json cells=Json::array();for(int row=1;row<=20000;++row)cells.push_back({{"row",row},{"col",1},{"input",std::to_string(row)}});return {{"revision",0},{"sheets",Json::array({{{"id","s"},{"name","Source"},{"cells",std::move(cells)}}})}};}
Json edit(const std::string& value){return Json::array({{{"type","set_cell"},{"sheet","s"},{"row",10000},{"col",1},{"input",value}}});}
void preparedCommit(){WorkbookSession session(source());std::string error;auto prepared=WorkbookSession::prepareTransaction(session.snapshot(),edit("changed"),&error);require(prepared&&prepared->changed()&&prepared->baseRevision()==0,"worker prepares a validated revision-bound transaction");require(!session.canUndo()&&session.cellAt("s",10000,1)->at("input")=="10000","preparation does not alter the live workbook or history");const auto* moved=&prepared->snapshot().at("sheets")[0].at("cells")[0];
 require(session.commitPrepared(0,*prepared,&error),"prepared transaction publishes successfully");require(&session.snapshotView().at("sheets")[0].at("cells")[0]==moved,"publication moves the prepared root without cloning source cells");require(session.cellAt("s",10000,1)->at("input")=="changed"&&session.historyBytes()<16384,"prepared publication retains a bounded cell undo delta");
 const auto recovery=session.takeRecoveryDelta();require(recovery.size()==1&&recovery[0]["baseRevision"]==0&&recovery[0]["revision"]==1,"prepared recovery envelope is published with the transaction");
 require(session.undo()&&session.cellAt("s",10000,1)->at("input")=="10000"&&!session.canUndo(),"one undo restores the previous workbook");require(session.redo()&&session.cellAt("s",10000,1)->at("input")=="changed","one redo restores the prepared edit");
}
void preparedPreview(){WorkbookSession session(source());const auto before=session.snapshot();auto first=WorkbookSession::prepareTransaction(session.snapshot(),edit("first"));require(first&&session.previewPrepared(0,first)&&!first&&session.hasPreview(),"prepared preview adopts the candidate without changing the canonical workbook");require(session.snapshot()==before&&session.previewView()&&session.previewView()->at("sheets")[0]["cells"][9999]["input"]=="first","prepared preview exposes the candidate while live data stays isolated");
 auto second=WorkbookSession::prepareTransaction(session.snapshot(),edit("second"));const auto* moved=&second->snapshot().at("sheets")[0].at("cells")[0];require(session.previewPrepared(0,second)&&second&&second->snapshot()["sheets"][0]["cells"][9999]["input"]=="first","replacing a prepared preview returns the retired candidate to its caller");
 std::unique_ptr<WorkbookSession::PreparedTransaction> retired;require(session.acceptPrepared(retired)&&retired&&!session.hasPreview()&&!session.previewView(),"accept uses the prepared history and returns retired roots for worker disposal");require(&session.snapshotView()["sheets"][0]["cells"][0]==moved&&session.cellAt("s",10000,1)->at("input")=="second","accept moves the prepared candidate directly");require(session.undo()&&session.cellAt("s",10000,1)->at("input")=="10000"&&!session.canUndo(),"replaced previews accept as exactly one undoable transaction");
 auto discarded=WorkbookSession::prepareTransaction(session.snapshot(),edit("discarded"));require(session.previewPrepared(session.snapshotView().at("revision"),discarded),"prepare a discardable preview");discarded=session.discardPrepared();require(discarded&&!session.hasPreview()&&session.cellAt("s",10000,1)->at("input")=="10000","discard returns the candidate for deferred destruction without publishing it");
}
void refusalAndCompatibility(){WorkbookSession session(source());std::string error;auto invalid=edit("leak");invalid.push_back({{"type","set_style"},{"sheet","s"},{"row",1},{"col",1},{"style",{{"fontSize",0}}}});const auto before=session.snapshot();require(!WorkbookSession::prepareTransaction(session.snapshot(),invalid,&error)&&!error.empty()&&session.snapshot()==before&&!session.canUndo(),"invalid prepared batches cannot mutate the live workbook or history");
 auto stale=WorkbookSession::prepareTransaction(session.snapshot(),edit("stale"));require(session.apply(0,edit("live")),"advance canonical revision after capture");const auto live=session.snapshot();const auto bytes=session.historyBytes();require(!session.commitPrepared(1,*stale,&error)&&session.snapshot()==live&&session.historyBytes()==bytes,"stale captured bases are refused even when caller supplies the latest revision");
 auto valid=WorkbookSession::prepareTransaction(session.snapshot(),edit("valid"));require(session.commitPrepared(1,*valid),"publish a current prepared transaction");const auto accepted=session.snapshot();require(!session.commitPrepared(2,*valid,&error)&&session.snapshot()==accepted,"prepared transactions cannot be replayed");
 WorkbookSession noOp(source());auto unchanged=WorkbookSession::prepareTransaction(noOp.snapshot(),edit("10000"));require(unchanged&&!unchanged->changed()&&noOp.commitPrepared(0,*unchanged)&&noOp.snapshotView()["revision"]==0&&!noOp.canUndo()&&noOp.takeRecoveryDelta().empty(),"unchanged prepared transactions create no revision, history or recovery entry");
 auto preview=WorkbookSession::prepareTransaction(noOp.snapshot(),edit("preview"));require(noOp.previewPrepared(0,preview)&&noOp.accept()&&!noOp.hasPreview()&&noOp.cellAt("s",10000,1)->at("input")=="preview","existing accept sees a prepared preview");preview=WorkbookSession::prepareTransaction(noOp.snapshot(),edit("discard"));require(noOp.previewPrepared(1,preview),"prepare compatibility discard");noOp.discard();require(!noOp.hasPreview()&&!noOp.previewView(),"existing discard sees a prepared preview");
 WorkbookSession conflict(source());preview=WorkbookSession::prepareTransaction(conflict.snapshot(),edit("candidate"));require(conflict.previewPrepared(0,preview)&&conflict.apply(0,edit("newer")),"create a prepared preview then a newer canonical edit");std::unique_ptr<WorkbookSession::PreparedTransaction> retired;require(!conflict.acceptPrepared(retired,&error)&&!retired&&conflict.hasPreview()&&conflict.cellAt("s",10000,1)->at("input")=="newer","prepared acceptance refuses stale previews without losing the current workbook");
 auto discarded=conflict.discardPrepared();require(discarded&&!conflict.commitPrepared(1,*discarded),"discarded prepared previews cannot later be published");
}
int main(){try{preparedCommit();preparedPreview();refusalAndCompatibility();std::cout<<"prepared session tests passed\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
